def compute(vars):
    beginning_liability = vars["v1"]
    ending_liability = vars["v2"]
    net_change = ending_liability - beginning_liability

    return {
        "value": net_change,
        "trace": {
            "beginning_liability": beginning_liability,
            "ending_liability": ending_liability,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
